const cecNar=(F,sd)=>{/* pkgNRC (Wall 6569 item 2): the side's own narrowings and withdrawals in its rounds 1 to 3 ("I narrow", "I withdraw", "I do not rest", "I no longer rest", "I drop", "I give up", "I set aside", "I retract"), each with the sentence before and after it, listed for the closing enforcer; not in a quotation, not after a condition; at most 12 */const st=x=>x.replace(/[*_]+/g,'').replace(/^[\s>#-]+/,'').trim(),SE=/(?<=[.!?]["”’')\]]*)\s+/;const NAR=/\b(?:I|we)\s+(?:now\s+|hereby\s+|therefore\s+|also\s+)?(?:narrow|withdraw|do\s+not\s+rest|no\s+longer\s+rest|drop|give\s+up|set\s+aside|retract)\b/i,CND=/\b(?:if|unless|whether|would|should|could|might)\b/i;
 const R=sd==='DEFENDER'?[['CR1','cr1'],['CR2','cr2'],['CR3','cr3']]:[['DR1','gr1'],['DR2','gr2'],['DR3','dr3']];const out=[];
 for(const [lab,k] of R){const ss=String(F[k]||'').split(/\n+/).flatMap(l=>l.split(SE)).map(st).filter(Boolean);for(let i=0;i<ss.length&&out.length<12;i++){const x=ss[i],m=x.match(NAR);if(!m)continue;const pre=x.slice(0,m.index);if(CND.test(pre)||(pre.match(/["“”]/g)||[]).length%2)continue;out.push('['+lab+'] '+((i>0?ss[i-1]+' ':'')+'>> '+x+' <<'+(i+1<ss.length?' '+ss[i+1]:'')).slice(0,500));}}
 return out;};
